const items=$input.all();
if(items.length!==1) throw new Error('Requires one telemetry item per execution');
const d=items[0].json;
const room=d.room??d.room_id;
const now=new Date();
const isManual=$('Manual Trigger').isExecuted;
const time=d.timestamp==null?now.getTime():Date.parse(d.timestamp);
let error='';
if(typeof room!=='string'||!room.trim()||typeof d.device_id!=='string'||!d.device_id.trim()) error='Thiếu room hoặc device_id';
else if(typeof d.occupancy!=='boolean') error='occupancy phải là boolean true/false';
else if(!Number.isFinite(time)||time>now.getTime()+30000||now.getTime()-time>120000) error='Timestamp không hợp lệ, quá cũ hoặc trong tương lai';

return [{json:{...d,room:typeof room==='string'?room.trim():room,valid:!error,error,
 evaluated_at:now.toISOString(),backend_base_url:'http://host.docker.internal:3001/api',
 test_mode:isManual,
 test_empty_seconds:isManual&&Number.isFinite(d.test_empty_seconds)?Math.max(0,Math.min(3600,d.test_empty_seconds)):0,
 test_hour:isManual&&Number.isInteger(d.test_hour)&&d.test_hour>=0&&d.test_hour<=23?d.test_hour:null}}];

const d=$('Telemetry dau vao').first().json;
const c=$('Doc Config').first().json;
const old=$input.first().json;
const parts=new Intl.DateTimeFormat('en-GB',{timeZone:c.timezone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(d.evaluated_at));
let hour=Number(parts.find(p=>p.type==='hour').value);
let minute=Number(parts.find(p=>p.type==='minute').value);
if(d.test_mode && d.test_hour!==null){hour=d.test_hour;minute=0;}
const m=hour*60+minute;
const inHours=c.allowed_start_minute<c.allowed_end_minute
 ? m>=c.allowed_start_minute && m<c.allowed_end_minute
 : m>=c.allowed_start_minute || m<c.allowed_end_minute;
const active=!inHours && d.occupancy;
const wasActive=old.room_id===d.room && old.active===true;
const opened=active&&!wasActive, closed=!active&&wasActive;
const message=opened?`Phòng ${d.room}: phát hiện có người ngoài giờ (${String(hour).padStart(2,'0')}:${String(minute).padStart(2,'0')})`:
 closed?`Phòng ${d.room}: điều kiện cảnh báo ngoài giờ đã kết thúc`:
 active?'Cảnh báo ngoài giờ vẫn đang tồn tại':'Không có điều kiện cảnh báo ngoài giờ';
return [{json:{
 state_to_save:{active,last_alert_at:opened?d.evaluated_at:(old.last_alert_at??null),observed_at:d.evaluated_at},
 result:{room:d.room,room_id:d.room,device_id:d.device_id,source:'WF09_SECURITY',timestamp:d.evaluated_at,
  wf09_status:opened?'ALERT':closed?'RECOVERED':'NO_CHANGE',
  severity:active?'CRITICAL':'NORMAL',after_hours:!inHours,security_active:active,
  local_time:`${String(hour).padStart(2,'0')}:${String(minute).padStart(2,'0')}`,timezone:c.timezone,
  should_notify:opened,test_mode:d.test_mode,message,
  incident_request:opened?{type:'AFTER_HOURS_SECURITY',severity:'CRITICAL',room_id:d.room,source:'WF09_SECURITY',message}:null,
  device_request:opened?{buzzer:'ON',reason:'AFTER_HOURS_SECURITY'}:null,
  security_buzzer_release:closed,
  incident_resolution_request:closed?{type:'AFTER_HOURS_SECURITY',room_id:d.room,source:'WF09_SECURITY',reason:'SECURITY_CONDITION_CLEARED'}:null}
}}];
